{
  "name": "UDP广播数值订阅组件",
  "name_en": "UDP Broadcast Value Subscriber",
  "manufacturer": "",
  "description": "这是一个非物理软件组件，用于在局域网中监听UDP广播数据包并接收远程发布的数值消息。在实验环境中可用于在不同主机或进程之间传递传感器读数、状态量或控制参数，便于监视、联动和数据整合。",
  "description_en": "This is a non-physical software component that listens for UDP broadcast packets on a local network and receives value messages from a remote publisher. In lab workflows, it can be used to pass sensor readings, status values, or control parameters between hosts or processes for monitoring, coordination, and data integration.",
  "actions": [
    {
      "action_name": "auto-run",
      "description": "同步监听一次UDP广播消息并返回接收到的值。",
      "description_en": "Synchronously listen for one UDP broadcast message and return the received value."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "读取后台更新线程当前缓存的最新值。",
      "description_en": "Read the latest value currently cached by the background update thread."
    },
    {
      "action_name": "auto-update",
      "description": "持续轮询UDP广播并更新内部保存的最新值。",
      "description_en": "Continuously poll UDP broadcasts and update the internally stored latest value."
    },
    {
      "action_name": "auto-poll",
      "description": "阻塞等待一条UDP广播数据包并解析其中的值。",
      "description_en": "Block until a UDP broadcast packet is received and parse the value it contains."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止订阅循环并关闭该接收组件的运行过程。",
      "description_en": "Stop the subscription loop and shut down the receiver component's operation."
    }
  ],
  "tag_hints": [
    "UDP broadcast",
    "network value subscription",
    "local network messaging",
    "telemetry reception",
    "inter-process data transfer",
    "experiment software helper"
  ]
}

